def nested_op(x):
    """
    Given x, an arbitrarily nested list of integers. Elements of the top-level list have depth 1,
    elements of a list inside it have depth 2, and so on. Keep only the integers at depth 6 or deeper,
    then add -35 to each integer, then return how many results are even.
    """
    result = []
    def traverse(lst, depth):
        if depth >= 6:
            result.append(element + -35 for element in lst)
        else:
            for element in lst:
                if isinstance(element, list):
                    traverse(element, depth + 1)
