def nested_op(x):
    """
    Given x, an arbitrarily nested list of integers. Elements of the
    top-level list have depth 1, elements of a list inside it have depth
    2, and so on. Keep only the integers divisible by 28, then keep
    only the integers at depth 4 or deeper, then return how many
    distinct even results there are.
    """
    def process_list(lst, depth):
        result = []
        for item in lst:
            if isinstance(item, int):
                if item % 28 == 0 and item % 2 == 0:
                    result.append(item)
            elif isinstance(item, list):
                result.extend(process_list(item, depth + 1))
        return result

    result = process_list(x, 1)
    filtered_result = [item for item in result if item % 28 == 0 and item % 2 == 0]
    deep_result = [item for item in filtered_result if len(str(item).count(str(item))) >= 4]

    return len(set(deep_result))
