                temp_list = current
                while isinstance(temp_list, list):
                    temp_list = temp_list[0]
                    depth += 1
                if current * depth**2 > 0 and current % 8 == 0:
                    result.append(current * depth**2)
    positive_results = [r for r in result if r > 0]
    if not positive_results:
        return 0
    else:
        return max(positive_results) - min(positive_results)
