def nested_op(x):
    """
    Applies a series of operations to a nested list of integers.

    Args:
        x: A list of integers with arbitrarily nested lists.

    Returns:
        The last negative result in left-to-right order after applying the operations,
        or 0 if there are no negative results.
    """
    stack = [(x, 1)]
    results = []

    while stack:
        current_list, depth = stack.pop()

        for element in current_list:
            if isinstance(element, int):
                if element % 29 == 0:
                    results.append(element)

            elif isinstance(element, list):
                stack.append((element, depth + 1))

    results.sort(reverse=True)

    for element in results:
        if element < 0:
            return element

    return 0
